def maxActiveSectionsAfterTrade(s, queries):
    n = len(s)
    starts, ends, kinds = [], [], []
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        starts.append(i)
        ends.append(j - 1)
        kinds.append(s[i])
        i = j
    m = len(starts)

    run_id = [0] * n
    for k in range(m):
        for p in range(starts[k], ends[k] + 1):
            run_id[p] = k

    # g[j]: gain of trading the '1' run j when both neighbours are full runs
    g = [-1] * m
    for k in range(1, m - 1):
        if kinds[k] == '1':
            g[k] = (ends[k - 1] - starts[k - 1] + 1) + (ends[k + 1] - starts[k + 1] + 1)

    # sparse table for range maximum of g
    sp = [g]
    k = 1
    while (1 << k) <= m:
        prev = sp[-1]
        half = 1 << (k - 1)
        sp.append([max(prev[x], prev[x + half]) for x in range(m - (1 << k) + 1)])
        k += 1

    def rmq(lo, hi):
        t = (hi - lo + 1).bit_length() - 1
        return max(sp[t][lo], sp[t][hi - (1 << t) + 1])

    total = s.count('1')
    res = []
    for l, r in queries:
        a, b = run_id[l], run_id[r]

        def length(k):
            if k == a:
                return ends[k] - l + 1       # run clipped on the left
            if k == b:
                return r - starts[k] + 1     # run clipped on the right
            return ends[k] - starts[k] + 1

        best = 0
        if b - a >= 2:
            for j in (a + 1, b - 1):
                if kinds[j] == '1':
                    best = max(best, length(j - 1) + length(j + 1))
            if a + 2 <= b - 2:
                best = max(best, rmq(a + 2, b - 2))
        res.append(total + best)
    return res
